import{_ as t}from"./chunks/5e9b3a79797b0d635c5a.DV-bj4dx.js";import{_ as o,o as a,c as i,a5 as n}from"./chunks/framework.DNkHA0lr.js";const m=JSON.parse('{"title":"Learn This Skill If You Want To Thrive In The Next 10 Years","description":"","frontmatter":{"title":"Learn This Skill If You Want To Thrive In The Next 10 Years","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/learn-this-skill-if-you-want-to-thrive-in-the-next-10-years.md","filePath":"en/letters/learn-this-skill-if-you-want-to-thrive-in-the-next-10-years.md"}'),r={name:"en/letters/learn-this-skill-if-you-want-to-thrive-in-the-next-10-years.md"};function s(l,e,h,p,u,d){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="learn-this-skill-if-you-want-to-thrive-in-the-next-10-years" tabindex="-1">Learn This Skill If You Want To Thrive In The Next 10 Years <a class="header-anchor" href="#learn-this-skill-if-you-want-to-thrive-in-the-next-10-years" aria-label="Permalink to &quot;Learn This Skill If You Want To Thrive In The Next 10 Years&quot;">​</a></h1><p>Dan Koe · 2022-08-13 · <a href="https://thedankoe.com/letters/learn-this-skill-if-you-want-to-thrive-in-the-next-10-years/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/learn-this-skill-if-you-want-to-thrive-in-the-next-10-years">返回中文译文</a></p><p><a href="https://www.youtube.com/embed/N8U5bzSD65Q?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>Ever since I can remember, I’ve had the goal of doing what I love for a living. Isn’t that what everyone wants?</p><p>My family, teachers, and even the people I was following online screamed at me to go down other paths.</p><p>So that’s what I did.</p><ul><li>Went to college and partied the entire time</li><li>Learned creative skills on the side</li><li>Started every online business imaginable</li><li>Learned to code because it was “lucrative”</li><li>Dropped out of college because it was wasting my time</li><li>Got a $55K/year job as an entry level web developer at a design agency</li></ul><p>Throughout this entire journey, my dream of “doing what I love” stuck in the back of my head. I was constantly reminded of it. There wasn’t a single moment from age 16-25 where I wasn’t working on a meaningful side project.</p><p>I still maintain this habit to this day. If it isn’t a business project, its a health project. This is how I get out of a rut, because the only reason I fall into a rut is psychic entropy, the mind tending toward disorder. Meaning I don’t have a goal, project, or priority to bring my focus to. When I spend time contemplating an area I want to make progress in, a vision will pop into my head after some time. The result? A dramatic boost in my quality of life. IF I act on that vision immediately.</p><p>My current projects are my new writing product and getting my compound lifts back up in the gym after an extended break from them. I <em>really</em> want to hit a 600 pound deadlift for some reason, even when I swore off of them a few years ago. It just sounds fun, risk aside (and risk adding to the fun and necessity of maintaining healthy habits).</p><p>Why am I telling you this?</p><p>Because I realized that nobody knew what they were talking about. I was taking career and life advice from people that hadn’t achieved what I wanted to achieve. In their closed mind the reality I wanted to create was impossible, yet I kept looping back to projects that I loved working on for the sake of maintaining my sanity.</p><p>Meaning, if I could find a way to monetize these “passion projects” then I would be set.</p><p>After years of trial and error with every “marketable skill” that people tell you to learn, I found the secret.</p><h2 id="why-writing" tabindex="-1">Why Writing? <a class="header-anchor" href="#why-writing" aria-label="Permalink to &quot;Why Writing?&quot;">​</a></h2><p><a href="https://open.spotify.com/embed/episode/0HLHWwyXRJtLYFFYH6GfdE?si=76beae14d2344f23&amp;utm_source=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>The backend of the internet is code. The frontend of the internet is media. If you want to thrive in the future, mastering code or media is your best bet. If you can master — or build a team — to take advantage of both (like <strong>marketing</strong> a <strong>software</strong> company) you shouldn’t have any worries about your life direction.</p><p>That is, being able to leverage <em>both</em> media and code. Which is more than possible with no-code tools like website builders, membership dashboards, email sending platforms, and other software that makes the one-person business model possible.</p><p>Do you not see the power in this? Does this <em>not</em> fuel you with immense energy to learn anything and everything available to you? Why have you not started failing at building a business when you can leverage code and learn media to build your mini-empire while spreading a message that you love spreading?</p><p>I learned to code in college, but I didn’t care for becoming a programmer. I wanted to freelance. So that’s what I tried to do. Web design, SEO, Facebook ads, content marketing, digital art, and every other skill under the sun… except for one.</p><p>There was a reason I failed at all of these business models. I didn’t understand what people actually wanted to buy. Not only that, I didn’t know how to get them to buy what I had to offer. That’s when I found Twitter. People were talking about online business and self-improvement. I got sucked in.</p><p>Some accounts that were posting insights about eCommerce mentioned a skill called “copywriting.” When I studied it deeper, that seemed to be the piece I was missing. Copywriting, in my definition, is persuasive writing. Think marketing and sales — two of the most important skills for making an income — but in written form.</p><p>As you could guess, this was the missing piece to my success. I started writing on Twitter to practice my writing, learned from my failures, and built a cumulative 350K follower audience across multiple platforms.</p><h3 id="again-why-writing" tabindex="-1">Again, Why Writing? <a class="header-anchor" href="#again-why-writing" aria-label="Permalink to &quot;Again, Why Writing?&quot;">​</a></h3><p>Media is the frontend of the internet. It’s how you capture, hold, and convert attention in a sea of self-deprecating memes and valueless content.</p><p><img src="'+t+'" alt=""></p><p>The foundation of media is writing.</p><ul><li><strong>Tweets?</strong> Writing.</li><li><strong>Threads?</strong> Writing.</li><li><strong>Newsletters?</strong> Writing.</li><li><strong>Blog posts?</strong> Writing.</li><li><strong>Cold emails?</strong> Writing.</li><li><strong>Ads of any form?</strong> Starts with writing.</li><li><strong>YouTube videos?</strong> Done best with written scripts.</li><li><strong>Instagram reels and TikToks?</strong> Like reading well-written tweets.</li><li><strong>Images on Instagram?</strong> Usually designed from a well-written quote or saying.</li><li><strong>Any other form of online marketing, advertising, or entertainment?</strong> Starts with writing.</li></ul><p>There’s a reason I can outperform every dude with six pack abs in terms of engagement and follower growth on Instagram.</p><p>High-impact digital writing.</p><p>If you want to become a master of media (and leverage no-code tools to distribute your writing and attract an audience) it’s pretty clear that writing needs to be the foundation of your one-person business.</p><p><strong>Before we dive in:</strong> Pre-sale for the 2 Hour Writer is now live. If you are an aspiring writer, one person business owner, or content creator that wants to implement my content ecosystem — <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">you can get 40% off here until the launch date.</a></p><h2 id="_9-steps-to-starting-a-one-person-writing-business" tabindex="-1">9 Steps To Starting A One-Person Writing Business <a class="header-anchor" href="#_9-steps-to-starting-a-one-person-writing-business" aria-label="Permalink to &quot;9 Steps To Starting A One-Person Writing Business&quot;">​</a></h2><p>I call myself a writer because that is what I do on a daily basis (even when it doesn’t seem like it on social media).</p><p>I’ve sustained a $40-$60,000 per month income by writing tweets, newsletters, and threads that get repurposed into Instagram posts, YouTube videos, LinkedIn posts, and the rest.</p><p>In reflection, and referring to the top of this letter, writing is the force multiplier that helped me make my previous salary month after month.</p><p>But, if you were to strip things down to only Twitter and a Newsletter, I would still maintain 85-90% of my income. I don’t promote often, if at all, on other platforms. I’m building leverage and cross platform authority for now.</p><p>Getting into it, here are the 9 steps to start your writing business.</p><h3 id="_1-choose-a-topic-you-can-t-shut-up-about" tabindex="-1">1) Choose A Topic You Can’t Shut Up About <a class="header-anchor" href="#_1-choose-a-topic-you-can-t-shut-up-about" aria-label="Permalink to &quot;1) Choose A Topic You Can’t Shut Up About&quot;">​</a></h3><p>Choosing a topic is what everyone struggles with in content creation. Let me make it simple for you.</p><p>Write down:</p><ul><li>Your favorite books</li><li>Your recent YouTube watch history</li><li>Your favorite social media accounts</li><li>What you would write about if money wasn’t an issue</li></ul><p>Seriously, pull out a piece of paper (or the notes app in your phone) and write down these all down.</p><p>Why are we doing this?</p><p>Because good writing isn’t about being professional. It’s about energy transfer. You will be excited to sit down and write everyday and that energy will show in your writing.</p><h3 id="_2-brainstorm-a-unique-perspective-you-have" tabindex="-1">2) Brainstorm A Unique Perspective You Have <a class="header-anchor" href="#_2-brainstorm-a-unique-perspective-you-have" aria-label="Permalink to &quot;2) Brainstorm A Unique Perspective You Have&quot;">​</a></h3><p>Novelty catches attention. Attention is a given if you want people to read what you write.</p><p>Novel perspectives are the best (and replicable way) to capture attention.</p><p>How do you come up with a novel perspective?</p><p>Braindump:</p><ul><li>Common problems associated with the topic</li><li>Benefits to overcoming those problems</li><li>Common goals associated with the topic</li><li>Roadblocks to achieving those goals</li><li>Personal experiences you’ve had</li></ul><p>Now, piece everything together and <em>explain it how you would if you were talking to a friend.</em></p><p>Don’t try to copy someones perspective or way of wording things. Say it in your own voice and let it <em>refine with time, effort, and practice.</em></p><p>If you want a guided challenge on how to do this, <a href="https://7daystogeniusideas.com/" target="_blank" rel="noreferrer">download my free 7 days to genius challenge.</a></p><p>If you don’t want to go through that, you can practice explaining topics in your own words and let experience create your perspective. You can do this by writing tweets everyday for a year. See what you can learn.</p><h3 id="_3-write-1000-words-on-the-topic" tabindex="-1">3) Write 1000+ Words On The Topic <a class="header-anchor" href="#_3-write-1000-words-on-the-topic" aria-label="Permalink to &quot;3) Write 1000+ Words On The Topic&quot;">​</a></h3><p>Every single piece of content online is based around a personal or professional problem.</p><p>Here’s how you can structure your writing.</p><ol><li>Explain the problem associated with the topic</li><li>Talk about your personal experiences with it</li><li>Optional: give context around the problem</li><li>Give step-by-step actionable advice on how to solve that problem (like this letter)</li></ol><p>Actionable advice is how you will build an audience at the start. I wouldn’t worry about being super insightful, that won’t help you grow until people know who you are.</p><p>Like how your favorite YouTuber didn’t start with vlogs. They started with what works, built an audience, then desaturated that market by doing whatever they want. Meaning that you can join in at anytime (this doesn’t only pertain to YouTube).</p><h3 id="_4-sign-up-for-a-blog-newsletter-software" tabindex="-1">4) Sign Up For A Blog &amp; Newsletter Software <a class="header-anchor" href="#_4-sign-up-for-a-blog-newsletter-software" aria-label="Permalink to &quot;4) Sign Up For A Blog &amp; Newsletter Software&quot;">​</a></h3><p>I rarely use fancy sales funnels and it’s rare to see me promote my products on social media anymore.</p><p>I use the 2 hour content ecosystem:</p><ul><li>1 newsletter a week</li><li>The newsletter is kept on the blog</li><li>1 thread a week from the newsletter</li><li>3 tweets a day from the newsletter topic</li></ul><p>People that only tweet have little authority and have trouble making sales and landing clients.</p><p>Authority comes from 1 of 2 things: <strong>depth or expertise.</strong></p><p>Long form content is where the money is made. Not with tweets and social media promotions.</p><p>For the sake of simplicity, I would sign up for Beehiiv, Revue, or Substack. We aren’t looking for fancy automations yet. All we want is a software that can send a newsletter, collect emails, and backlog that newsletter as a blog post (crucial point that no-one takes advantage of) so we can plug those as mini-salesmen or individual lead magnets under our other content.</p><h3 id="_5-repurpose-the-actionable-section-of-the-newsletter" tabindex="-1">5) Repurpose The Actionable Section Of The Newsletter <a class="header-anchor" href="#_5-repurpose-the-actionable-section-of-the-newsletter" aria-label="Permalink to &quot;5) Repurpose The Actionable Section Of The Newsletter&quot;">​</a></h3><p>We know that actionable step-by-step advice is the most beginner friendly and potent tool for social growth. If you don’t know how to grow, chances are that you are trying to be too clever and insightful from the start — when all you need to do is give actionable advice related to your talking point (and pair it with step 6 of this newsletter).</p><p>Pair actionable advice with a Twitter thread and you have the potential to gain 100-1000 followers your first time around. I see this happen all the time.</p><p>How do we make this easy?</p><p>Turn the actionable section of the newsletter you wrote into a Twitter thread. Simple as that. I show you exactly how in my new course, <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a>, to make sure that it is written for maximum impact.</p><h3 id="_6-learn-how-to-network-grow-on-the-platform" tabindex="-1">6) Learn How To Network &amp; Grow On The Platform <a class="header-anchor" href="#_6-learn-how-to-network-grow-on-the-platform" aria-label="Permalink to &quot;6) Learn How To Network &amp; Grow On The Platform&quot;">​</a></h3><p>When you start playing a game, you don’t just dive in and start playing. You’ll have no idea what you are doing, get angry, and quit.</p><p>The reason you’ve tried and failed at growing on different social platforms is because you think it is as simple as posting good content. Not in the slightest.</p><p>You grow on social media platforms by getting more eyes on your profile. How do you do that?</p><ul><li>People <em>sharing</em> your content to their audience</li><li>Networking with similar follower accounts and growing together</li><li>Commenting on larger accounts posts so people can see your comments and click to your account</li><li>Make your long form content (newsletter) so good that people can’t help but talk about it</li><li>Join a community (like <a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">Modern Mastery</a>) to meet people that are on the same path as you.</li><li>Optional but less taboo than you think: paying big accounts for shares (retweets, story shares on Instagram, or even something as simple as a comment because that still exposes your content to their audience).</li></ul><p>Of course, you still need to have good content and an optimized profile if you want people to follow you.</p><p>It’s called <em>social</em> media for a reason. You have to interact with others, make friends, and help each other grow.</p><p>You can do without this, but it will be painstakingly slow and you’ll turn into one of those accounts that just whines all day about how social growth is unfair. Don’t hate the player, hate the game.</p><h3 id="_7-turn-ideas-into-impactful-tweets" tabindex="-1">7) Turn Ideas Into Impactful Tweets <a class="header-anchor" href="#_7-turn-ideas-into-impactful-tweets" aria-label="Permalink to &quot;7) Turn Ideas Into Impactful Tweets&quot;">​</a></h3><p>From your newsletters and threads, your mind should be flooded with tweet ideas. Tweets are short and punchy writing that get people to react.</p><p>My favorite way of writing tweets is with the framework I developed: PPP</p><ul><li>Pull</li><li>Perspective</li><li>Punchline</li></ul><p>Pull them in with something that catches attention (like a number or percentage), give a unique perspective that came from personal experience and critical thought, and wrap it all up in a way that makes sense.</p><p>Perspective and punchline often tie into one another, usually in one-liners like this:</p><blockquote><p>People will spend 10 hours worrying about a task that takes 10 minutes to complete.</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1556598603065475072?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">August 8, 2022</a></p></blockquote><p>You can also see this framework separated well in list tweets (use these when you give actionable advice):</p><blockquote><p>Most people will spend:\\</p><p>8 hours on someone else’s dreams<br> 4 hours hiding from their own<br> 2 hours going through the motions\\</p><p>16 hours awake<br> 24 hours asleep\\</p><p>It doesn’t have to take 40 years and a retirement plan realize that a participation trophy isn’t fulfilling.</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1556571426794127361?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">August 8, 2022</a></p></blockquote><p>This is one of many tweet writing methods. Your best bet is to study the accounts you listed in step 1 and follow the <a href="https://thedankoe.com/how-to-copy-your-way-to-success-instead-of-mediocrity/" target="_blank" rel="noreferrer">Intelligent Imitation process</a>. Emulate their writing as if their tweets were training wheels, dissect why it did well, and try to replicate in your own way.</p><h3 id="_8-develop-a-writing-system" tabindex="-1">8) Develop A Writing System <a class="header-anchor" href="#_8-develop-a-writing-system" aria-label="Permalink to &quot;8) Develop A Writing System&quot;">​</a></h3><p>This newsletter goes over everything I would do if I had to start over from zero.</p><p>I wasted 2 years testing sales funnels, different content writing methods, and finding the best way to sustain a high monthly income with writing.</p><p>My best advice?</p><p>Create a system from the start and refine it over time. Then, if you want to package it up and sell it in the future, you can. That’s what the one-person business model does. They get results with a system they’ve tested on themselves (to solve their own problem) and then sell it to others — because by the time the system is perfected, you have ample experience and authority to bank on.</p><p>I use Notion to create systems to make it easy on myself. No other fancy software necessary.</p><p>These systems can start as step-by-step list of what you need to do on a daily or weekly basis. Then you can start getting fancy with Notions cool features.</p><h3 id="_9-branch-out-to-other-platforms" tabindex="-1">9) Branch Out To Other Platforms <a class="header-anchor" href="#_9-branch-out-to-other-platforms" aria-label="Permalink to &quot;9) Branch Out To Other Platforms&quot;">​</a></h3><p>I overcomplicated this for the longest time.</p><p>I’ve grown to 230K on Instagram, 23K on LinkedIn, and 7K on YouTube with my <em>writing</em> skills.</p><p>I get more engagement than dudes with adonis physiques because my writing hits harder than their chiseled abs.</p><p>All I do is copy, paste, and record the content that I’ve already written in my newsletters, threads, and tweets. You could even turn your best tweets into TikTok or reel scripts.</p><p>Master Twitter first, gain some authority, then use your best tweets to break into new platforms (since those ideas are already validated to do well).</p><h3 id="let-s-recap-on-how-you-can-start-your-writing-business" tabindex="-1">Let’s Recap On How You Can Start Your Writing Business <a class="header-anchor" href="#let-s-recap-on-how-you-can-start-your-writing-business" aria-label="Permalink to &quot;Let’s Recap On How You Can Start Your Writing Business&quot;">​</a></h3><p>With 1-2 hours a day (considering you have a freelance, consulting, or digital product to sell with the traffic / distribution you are building) you can pull in a higher monthly income than some of the highest paid doctors, without spending a dime on a college degree.</p><p>We live in an age of authenticity where nobody is authentic. People don’t want professionalism. They want individuality and a sense of belonging with people that “get them.”</p><p>I am nowhere near the best writer, yet I make more than 99% of the writers out there. Funny how that works.</p><p>Here’s a recap of what we went over:</p><ul><li>Choose a topic you can’t shut up about</li><li>Brainstorm a unique perspective you have</li><li>Write 1000+ words in a structured way</li><li>Sign up for a newsletter / blog software and post it</li><li>Turn the actionable section into a viral Twitter thread</li><li>Learn how to network and get eyes on your content</li><li>Turn ideas from your newsletter into tweets and plug your newsletter under it to “read more” (this will grow your email list)</li><li>Develop a system to make writing take less than 4-6 hours a week</li><li>Branch out to other platforms when you are ready</li></ul><p>Lastly, if you have a product or service, you wouldn’t promote it on the timeline.</p><p>That’s the beauty in this content ecosystem. You build authority with depth in your newsletters, post them as blogs, and plug your offer there.</p><p>Now, you plug relevant newsletters under your tweets and threads everyday. No salesy promotions, no spamming on the timeline. Just perfected social media growth and more sales than any 10 step sales funnel you could build (I’ve tested).</p><h3 id="the-2-hour-writer-is-live" tabindex="-1">The 2 Hour Writer Is Live! <a class="header-anchor" href="#the-2-hour-writer-is-live" aria-label="Permalink to &quot;The 2 Hour Writer Is Live!&quot;">​</a></h3><p>If you are a creative or one-person business that wants to:</p><ul><li>Implement the 2 hour content ecosystem for social growth and authority</li><li>Generate unlimited viral content ideas without templates</li><li>Learn to write in their own unique voice and make their ideas interesting enough to share</li></ul><p><a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">Then check out everything else that is included in the 2 Hour Writer here.</a></p><p>Hope to see you inside!</p><p>— Dan “you don’t need an english degree to type words on the internet” Koe</p>',120)])])}const g=o(r,[["render",s]]);export{m as __pageData,g as default};
